import { Validation } from '../FileMultiUploader.types';

export const validateFileType = (file: File, acceptedTypes?: string): boolean => {
  if (!acceptedTypes) {
    return true;
  }

  const typesArray = acceptedTypes.split(',');
  const fileType = file.type;
  const fileExtension = `.${file.name.split('.').pop()}`;
  return typesArray.some((type) => {
    const trimmedType = type.trim();
    if (trimmedType.startsWith('.')) {
      return fileExtension === trimmedType;
    }
    if (trimmedType.endsWith('/*')) {
      return fileType.startsWith(trimmedType.slice(0, -2));
    }
    return fileType === trimmedType;
  });
};

export const validateFileSize = (file: File, maxSize: number): boolean => file.size <= maxSize;

export const validateFile = (file: File, validations: Validation[]): string[] => {
  const errors: string[] = [];

  validations.forEach((validation) => {
    if (!validation.validation(file)) {
      errors.push(validation.errorMessage);
    }
  });

  return errors;
};

interface FormatOptions {
  fixedPoints?: number;
  separator?: string;
}

export const formatFileSize = (size: number, options: FormatOptions = {}): string => {
  const { fixedPoints = 1, separator = '.' } = options;
  const i = size === 0 ? 0 : Math.floor(Math.log(size) / Math.log(1000));
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  let formattedSize = (size / 1000 ** i).toFixed(fixedPoints);
  // Remove trailing zeros after the decimal point
  formattedSize = formattedSize.replace(/(\.[0-9]*[1-9])0+$|\.0*$/, '$1');
  if (separator !== '.') {
    formattedSize = formattedSize.replace('.', separator);
  }
  return `${formattedSize}${sizes[i]}`;
};
